G=load()
def solve(I):
    H,W=len(I),len(I[0]); O=[r[:] for r in I]
    pts=[(r,c) for r in range(H) for c in range(W) if I[r][c]==2]
    # components by 8-connectivity
    seen=set(); comps=[]
    for p in pts:
        if p in seen: continue
        st=[p]; comp=set()
        while st:
            r,c=st.pop()
            if (r,c) in comp: continue
            comp.add((r,c)); seen.add((r,c))
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    q=(r+dr,c+dc)
                    if q in pts and q not in comp: st.append(q)
        comps.append(comp)
    def corners(comp):
        rs=[r for r,c in comp]; cs=[c for r,c in comp]
        return [(min(rs),min(cs)),(min(rs),max(cs)),(max(rs),min(cs)),(max(rs),max(cs))]
    for i in range(len(comps)):
        for j in range(len(comps)):
            if i==j: continue
            ci=corners(comps[i]); cj=corners(comps[j])
            for a in ci:
                for b in cj:
                    if a==b: continue
                    if (a[0]==b[0] or a[1]==b[1]):
                        r0,c0=min(a,b[0]); r1,c1=max(a[0],b[0])
                        if a[0]==b[0]:  # horizontal
                            lo,hi=sorted((a[1],b[1]))
                            seg=[(a[0],c) for c in range(lo+1,hi)]
                        else:
                            lo,hi=sorted((a[1],b[1]))
                            seg=[(r,b[1]) for r in range(lo+1,hi)]
                        if all(O[r][c]==0 for r,c in seg) and len(seg)>=1:
                            for r,c in seg: O[r][c]=1
    return O
